    "Melody":             {kopf:"human",haut:"light",ruest:"leder_frau",ruestTon:"dunkel",krone:true,geschlecht:"w",haar:"haar_lang",haarTon:"pink"},

    // ===================================================================================
    // BATCH 5 (80 neue Eintraege) — zehn parallele Agenten, je 10 Spieler aus der
