    "Lynara":             {kopf:"human",haut:"light",ohren:true,ruest:"leder_frau",ruestTon:"gold",haar:"haar_lang",haarTon:"platinum",krone:true,geschlecht:"w"},
    // Bild: gefluegelte goldene Lichtgestalt, haelt einen langen Stab/Zepter mit
