    "Byrd":               {kopf:"human",haut:"brown",geschlecht:"w",zwiebelkopf:true,ruest:"leder_frau",ruestTon:"gold"},
    // effekt "frost"/"kopf" (25.08., Ausbau ueber Feuer hinaus, Bildbefund oben in
