  const STANDARD_ARCHETYP_ID="fighter";
  // >>> ENDE GENERIERT: kampf-archetyp-daten

  // AUFLOESUNG SELBST — Logik, keine Daten, deshalb von Hand geschrieben statt generiert
  // (mechanisch identisch zu lib/battle/combat-archetype-resolver.ts, s. Kommentar oben
  // an PLATZHALTER_ARCHETYP; scripts/pruefe-kampf-archetyp-abgleich.ts misst nach, dass
  // beide Fassungen fuer dieselben Spieler dasselbe liefern).
  //
  // SCHRITT 1 — welcher der 14 breiten Buckets (player-generator-archetypes.ts) passt am
  // besten zu Klasse+Unterklassen+Traits? Klasse in preferredClasses +3, in
  // disallowedClasses -6, je Unterklasse in preferredSubclasses +2, je Trait in
  // preferredPositiveTraits/preferredNegativeTraits +1, je Identitaets-Schluesselwort-
  // Treffer (Klasse ODER eine Unterklasse, normalisiert auf "klein-mit-bindestrich") +1,5.
  // Bleibt JEDER Bucket bei Score 0 (kein einziges Kriterium traf), gilt der explizite
  // Default "warrior" statt des ersten Objekt-Schluessels.
  const normKlasseFuerArchetyp=(s)=>String(s||"").trim().toLowerCase().replace(/\s+/g,"-");
  function bestimmeBreitenBucket(p){
    const klasse=p.c, subs=p.sub||[];
    const identitaeten=[normKlasseFuerArchetyp(klasse),...subs.map(normKlasseFuerArchetyp)];
    let bester=null,besterScore=-Infinity;
    for(const key in BREITE_ARCHETYPEN){
      const b=BREITE_ARCHETYPEN[key];
      let score=0;
      if(b.preferredClasses.includes(klasse))score+=3;
      if(b.disallowedClasses.includes(klasse))score-=6;
      for(const s of subs)if(b.preferredSubclasses.includes(s))score+=2;
      for(const t of (p.tp||[]))if(b.preferredPositiveTraits.includes(t))score+=1;
      for(const t of (p.tn||[]))if(b.preferredNegativeTraits.includes(t))score+=1;
      for(const kw of b.identityKeywords)if(identitaeten.includes(kw))score+=1.5;
      if(score>besterScore){besterScore=score;bester=key;}
    }
    return besterScore>0?bester:"warrior";
  }
  // SCHRITT 2 — Kandidatenmenge: Bildbefund (falls der Spielername vorliegt) ersetzt die
  // Vereinigung, sonst Vereinigung ueber alle Unterklassen (Reihenfolge stabil: erste
  // Unterklasse zuerst, keine Duplikate) — exakt `archetypenFuer()` aus
  // subclass-archetypes.ts, nur mit IDs statt Archetype-Objekten.
  function kandidatenArchetypIds(p){
    const bild=BILDBEFUNDE_ARCHETYPEN[p.n];
    if(bild)return bild;
    const gesehen=new Set(),raus=[];
    for(const s of (p.sub||[])){
      for(const id of (UNTERKLASSE_ARCHETYPEN[s]||[])){
        if(!gesehen.has(id)){gesehen.add(id);raus.push(id);}
      }
    }
    return raus;
  }
  // SCHRITT 3 — aus der Kandidatenmenge genau EINEN waehlen: hoechstes Skalarprodukt
  // zwischen dem normierten hp/atk/def/spd-Profil des Kandidaten und dem Zielvektor des
  // Buckets (`BREITE_ARCHETYPEN[bucket].ziel`). Ein einzelner Kandidat ist trivial, eine
  // leere Menge faellt auf STANDARD_ARCHETYP_ID zurueck (dokumentierter Default, s. dort).
  function kampfArchetypVon(p){
    const kandidaten=kandidatenArchetypIds(p);
    if(!kandidaten.length)return ARCHETYP_KAMPFWERTE[STANDARD_ARCHETYP_ID];
    if(kandidaten.length===1)return ARCHETYP_KAMPFWERTE[kandidaten[0]]||ARCHETYP_KAMPFWERTE[STANDARD_ARCHETYP_ID];
    const ziel=BREITE_ARCHETYPEN[bestimmeBreitenBucket(p)].ziel;
    let bester=null,besterScore=-Infinity;
    for(const id of kandidaten){
      const a=ARCHETYP_KAMPFWERTE[id];
      if(!a)continue;
      const score=a.hp*ziel.hp+a.atk*ziel.atk+a.def*ziel.def+a.spd*ziel.spd;
      if(score>besterScore){besterScore=score;bester=a;}
    }
    return bester||ARCHETYP_KAMPFWERTE[STANDARD_ARCHETYP_ID];
  }

  const KEYS=["LP","ANG","VER","TMP","AUS"];
  const LONG={LP:"Lebenspunkte",ANG:"Angriff",VER:"Verteidigung",TMP:"Tempo",AUS:"Ausdauer"};
  // JEDER BEFEHL HAT EINE EXAKT BESCHREIBBARE WIRKUNG. Der Tooltip unten ist ein
  // Versprechen — was dort steht, tut die Simulation, sonst darf es dort nicht stehen.
  const ORDERS=[
    ["mitlinie","Mit der Linie",
      "Rückt zusammen mit den eigenen Leuten vor und hält so viel Abstand zur Linie, wie sein Zusammenhalt vorgibt. Greift an, was in Reichweite kommt."],
    ["hinter","Hinter den Eigenen",
      "Bleibt hinter der vordersten eigenen Einheit und überquert diese Linie nie. Er darf seitlich ausweichen und nachrücken, verfolgt aber keinen Gegner über die Front hinaus. Steht er über 4,5 s ganz ohne Ziel da, oder sind auf einer Seite nur noch zwei übrig, fällt die Beschränkung und er greift an."],
    ["decken","Rücken decken",
      "Bleibt in der eigenen Hälfte. Greift nur an, wer die eigene Hälfte betritt — und läuft ihm dann entgegen. Ohne Eindringling hält er seine Position, aber nicht länger als 4,5 s: dann sucht er den Kampf. Sind auf einer Seite nur noch zwei übrig, fällt die Hälften-Beschränkung ganz."],
    ["flanke","Flanke",
      "Läuft an den Spielfeldrand und außen herum in die gegnerische Hälfte. Unterwegs wehrt er sich nur gegen Gegner in unmittelbarer Nähe. Angekommen greift er den an, der bis dahin am meisten angerichtet hat — nicht stur die hinterste Reihe."],
    ["verfolgen","Verfolgen",
      "Bleibt an seinem Ziel dran, quer über das ganze Feld. Ignoriert die Formation vollständig — er kehrt nicht zur Linie zurück."]
  ];
  // Gilt fuer JEDEN Befehl und steht deshalb in jedem Tooltip — sonst waere jeder
  // Tooltip an dieser Stelle unvollstaendig.
  const DURCHBRUCH=" Durchbruch: Wer sein Ziel über 3 s vor Augen hat und trotzdem nicht "+
    "herankommt, gilt als abgefangen — ab dann ignoriert er die Störer und die eigene Linie "+
    "und geht durch. Aufhalten lässt er sich nur noch, indem man ihn umbringt.";
  // Welchen Befehl jede Persoenlichkeit von sich aus waehlt.
  const PERSORD={bollwerk:"hinter",draufgaenger:"verfolgen",duellant:"mitlinie",
    schleicher:"flanke",beschuetzer:"decken",opportunist:"mitlinie"};
  const ORDTIP=Object.fromEntries(ORDERS.map(([v,l,t])=>[v,{l,t:t+DURCHBRUCH}]));
  // Persoenlichkeit setzt die Grundveranlagung. Der Befehl VERSCHIEBT sie, er ersetzt sie nicht.
  // form  = Formationstreue: wie nah bleibt er der eigenen Linie
  // opp   = Opportunismus:   wie bereitwillig wechselt er das Ziel
  // selb  = Selbsterhaltung: zieht er sich zurueck, wenn es eng wird
  const PERS={
    bollwerk:{l:"Bollwerk",form:85,opp:20,selb:35,ziel:"naechster"},
    draufgaenger:{l:"Draufgänger",form:20,opp:75,selb:5,ziel:"naechster"},
    duellant:{l:"Duellant",form:55,opp:30,selb:45,ziel:"gefaehrlichster"},
    schleicher:{l:"Schleicher",form:15,opp:55,selb:80,ziel:"hinten"},
    beschuetzer:{l:"Beschützer",form:75,opp:45,selb:50,ziel:"naechster"},
    opportunist:{l:"Opportunist",form:40,opp:90,selb:65,ziel:"schwaechster"}
  };
  // Der Befehl verschiebt die drei Werte. So bleibt die Persoenlichkeit spuerbar,
  // die Taktik aber wirksam — genau die Schichtung aus Eslabong.
  // DREI FUENFERSKALEN statt Zahlenschieber — die Eslabong-Struktur, und sie ist besser:
  // benannte Stufen kann man lesen, „Formationstreue 62" nicht.
  const HALTUNG=[["defensiv","Defensiv"],["vorsichtig","Vorsichtig"],["ausgewogen","Ausgewogen"],["offensiv","Offensiv"],["wild","Ungestüm"]];
  const ZUSAMMEN=[["eigen","Eigenmächtig"],["locker","Locker"],["ausgewogen","Ausgewogen"],["eng","Eng"],["dicht","Dicht"]];
  const BINDUNG=[["opportun","Opportunistisch"],["flexibel","Flexibel"],["ausgewogen","Ausgewogen"],["treu","Zielstrebig"],["unbeirrt","Unbeirrt"]];
  // ZIELPRIORITAET — uebersteuert die Neigung der Persoenlichkeit.
  // Welche Zielwahl jede Persoenlichkeit von sich aus trifft — das ist der Stern-Eintrag.
  //
  // CHRIS AM 13.09. ZUM LIVE-TDM: „die charaktere suchen sich anscheinend einen gegner und
  // hauen drauf aber es gibt gar nicht ne dynamik wo manche versuchen laut ihrem charakter
  // oder stil eher die backrow oder sonstwas standardmaessig zu attacken."
  //
  // Er hat recht, und diese Tabelle war der Grund. DREI der sechs Archetypen standen auf
  // "naechster" — bollwerk, draufgaenger UND beschuetzer. "naechster" ist aber gar keine
  // Neigung, sondern die Abwesenheit einer: rein geometrisch, ohne jeden Bezug zur Reihe,
  // zur Rolle oder zum Charakter. Von sechs Persoenlichkeiten hatte damit genau EINE
  // (schleicher) ueberhaupt eine Stellungsabsicht — und die war ausgerechnet in Mini-DM ein
  // stiller Leerlauf (s. hintersteReihe weiter unten). Wer keinen Schleicher im Kader hatte,
  // sah im ganzen Kampf niemanden, der etwas anderes versuchte als den naechsten Koerper.
  //
  // ZWEI der drei bleiben unveraendert, und zwar begruendet:
  //   duellant -> "bedrohung" und opportunist -> "schwach" sind echte, eingemessene
  //   Neigungen und werden hier NICHT verwaessert.
  //   bollwerk -> "naechster" bleibt ebenfalls: das Bollwerk IST der Schirm, "nimm, was auf
  //   dich zukommt" ist fuer ihn eine Charakterisierung und kein Platzhalter.
  // Die beiden anderen bekommen je eine eigene, STELLUNGSBEZOGENE Neigung (s. ZIELE):
  //   draufgaenger -> "speer"   (die Spitze der gegnerischen Formation aufbrechen)
  //   beschuetzer  -> "schild"  (den wegschlagen, der an den eigenen Leuten haengt)
  // Fuenf verschiedene Neigungen auf sechs Archetypen, DREI davon lesen die Aufstellung
  // (speer/hinten/schild) statt nur den Abstand.
  //
  // NICHT der Weg, den `docs/design/arena-mini-dm-tdm-battlefield-rollout-plan.md`
  // Abschnitt 4.1 als "Option A" empfiehlt (alle drei "naechster" auf "bedrohung"). Der
  // Plan ist aelter als Chris' Meldung und beantwortet eine ANDERE Frage — er sucht den
  // staerksten rho-Hebel, Chris verlangt sichtbare VIELFALT. Option A haette vier von sechs
  // Archetypen auf dieselbe Neigung gelegt und damit genau die Gleichfoermigkeit vergroessert,
  // die er beanstandet; der Plan benennt diesen Nachteil selbst ("Fokusfeuer [...] wird zum
  // Normalfall, nicht mehr zur Ausnahme"). Option C desselben Abschnitts — "Reihe/Formation
  // bleibt der Skill-Kanal" — ist dagegen genau das, was der zweite Teil dieser Aenderung
  // umsetzt (s. reihenAnker weiter unten).
  const PERSZIEL={bollwerk:"naechster",draufgaenger:"speer",duellant:"bedrohung",
    schleicher:"hinten",beschuetzer:"schild",opportunist:"schwach"};
  const ZIELE=[
    ["bedrohung","Größte Bedrohung","Greift den Gegner mit dem höchsten Angriffswert an, egal wie weit er entfernt ist."],
    ["schwach","Angeschlagensten","Greift den Gegner mit den wenigsten verbleibenden Lebenspunkten an — Fokusfeuer, um ihn schnell auszuschalten."],
    ["naechster","Nächsten","Greift immer den nächststehenden Gegner an. Läuft niemandem hinterher."],
    ["hinten","Hintere Reihe","Sucht sich ein Ziel in der hintersten besetzten gegnerischen Reihe. Steht der Gegner nur noch in einer Reihe, gilt wieder die natürliche Neigung."],
    ["speer","Spitze aufbrechen","Greift den Gegner an, der am weitesten vorgerückt ist — die Spitze der gegnerischen Formation. Mehrere mit diesem Ziel bündeln sich auf denselben Vorstoß, statt sich auf je einen Nachbarn zu verteilen."],
    ["schild","Kameraden freischlagen","Greift nicht den an, der IHM am nächsten steht, sondern den, der einem seiner Leute am nächsten steht. Er räumt den weg, der an der eigenen Linie hängt."],
    ["heiler","Heiler zuerst","Greift bevorzugt gegnerische Heiler an. Steht keiner im Feld, gilt wieder die natürliche Neigung."]
  ];
  const ZIELTIP=Object.fromEntries(ZIELE.map(([v,l,t])=>[v,{l,t}]));
  // Wer heilt: die Unterklasse entscheidet. Alle vier gibt es im Spielstand bereits
  // (Cleric 68, Healer 59, Shaman 93, Druid 101).

  const HEILER=new Set(["Cleric","Healer","Shaman","Druid"]);
  const istHeiler=(p)=>(p.sub||[]).some(x=>HEILER.has(x));

  const SKTIP={
    h:"Haltung steuert, wann jemand abbricht. Defensiv löst sich schon bei knapp der Hälfte seiner Lebenspunkte aus dem Kampf und fällt zurück; ungestüm kämpft bis zum Ende weiter und zieht sich nie zurück.",
    z:"Zusammenhalt bestimmt, wie weit sich jemand von der eigenen Linie entfernen darf. Dicht bleibt eng bei den Kameraden und kehrt zurück; eigenmächtig läuft dem Ziel hinterher, auch quer über das Feld.",
    ziel:"Wen dieser Spieler bevorzugt angreift. Natürlich heißt: seine Persönlichkeit entscheidet — ein Duellant sucht den Stärksten, ein Opportunist den Schwächsten, ein Bollwerk den Nächsten.",
    b:"Bindung bestimmt, wie oft neu gezielt wird. Opportunistisch prüft alle 0,35 Sekunden und wechselt auf das lohnendste Ziel; unbeirrt bleibt bis zu 2,8 Sekunden am einmal gewählten Gegner und ignoriert Angreifer im Rücken. Sie entscheidet außerdem, was er tut, wenn ihn jemand abfängt: ab 55 stellt er sich dem Abfangenden, darunter geht er weiter — und kassiert dafür beim Lösen einen Trennschlag mit halbem Schaden."
  };
  const SK=(arr,v)=>Math.max(0,arr.findIndex(x=>x[0]===v))/(arr.length-1);
  // Jede Persoenlichkeit hat ihre eigene Grundstellung auf den drei Skalen.
  const PERSDEF={
    bollwerk:{h:"vorsichtig",z:"dicht",b:"treu"},
    draufgaenger:{h:"wild",z:"eigen",b:"opportun"},
    duellant:{h:"ausgewogen",z:"ausgewogen",b:"treu"},
    schleicher:{h:"vorsichtig",z:"eigen",b:"flexibel"},
    beschuetzer:{h:"defensiv",z:"eng",b:"ausgewogen"},
    opportunist:{h:"ausgewogen",z:"locker",b:"opportun"}
  };
    const clamp=(v)=>Math.max(0,Math.min(100,Math.round(v)));
  // "natürlich" heisst: die Persoenlichkeit entscheidet. Genau der Kniff aus dem Vorbild —
  // man stellt nur ein, was einen wirklich stoert, der Rest bleibt Charakter.
  const takt={};
  // PERSOENLICHKEIT WAEHLT ZIEL UND MUT, DAS HANDWERK IST FUER ALLE GLEICH (P1, 07.10.,
  // docs/design/arena-zielwahl-opus-empfehlung-02-10.md Abschnitt 4.1, von Chris freigegeben).
  //
  // "Persoenlichkeit" steuert in der Arena vier Kanaele: Zielneigung (PERSZIEL), Haltung (h),
  // Zusammenhalt (z) und Bindung (b). Die kontrafaktische Zerlegung (dort Abschnitt 2) zeigt:
  // die eignungsfremde Fehlordnung tragen NICHT Zielneigung und Haltung, sondern z und b —
  // der Draufgaenger ("eigen"/"opportun") lief allein ueber das Feld, zielte staendig um und
  // liess sich von jedem Abfaenger stellen, und verlor damit Menge statt nur Stil.
  //
  // Eine Disziplin erklaert ueber `ARENA_ART[d].persHandwerk` (Liste aus "z"/"b"), welche dieser
  // Skalen bei ihr Handwerk sind; die stehen dann fuer alle sechs Persoenlichkeiten auf der
  // Skalenmitte "ausgewogen" (gemessen V9 bzw. V5 — "zielstrebig" als Mitte waere messbar
  // schlechter, Dokument 2.1). Zielneigung und Haltung bleiben Charakter, die manuellen
  // Taktik-Regler (`takt`) gehen weiter vor. Fehlt das Feld (jede Nicht-Arena-Disziplin, oder
  // eine Arena-Disziplin mit `[]`), liefert persDefVon() exakt PERSDEF — bit-identisch.
  // PERSDEF selbst bleibt unveraendert (das Sandsack-Finale liest es direkt).
  //
  // BEWUSST NICHT K1 (arena-zielwahl-umsetzung.md, zweimal gescheitert): die Zielvielfalt
  // bleibt vollstaendig erhalten, und an keiner Stelle wird die Eignung gelesen.
  const HANDWERK_MITTE={z:"ausgewogen",b:"ausgewogen"};
  function persDefVon(pk,dId){
    const def=PERSDEF[pk]||PERSDEF.duellant;
    const frei=(dId&&ARENA_ART[dId]&&ARENA_ART[dId].persHandwerk)||[];
    if(!frei.length)return def;
    return {h:def.h,
            z:frei.includes("z")?HANDWERK_MITTE.z:def.z,
            b:frei.includes("b")?HANDWERK_MITTE.b:def.b};
  }
  function behav(name,dId){
    const pk=persOf[name]||"duellant",def=persDefVon(pk,dId),t=takt[name]||{};
    const h=t.h||def.h, z=t.z||def.z, b=t.b||def.b;
    return{
      h,z,b,
      // Formationstreue steigt mit "Zusammenhalt", Opportunismus faellt mit "Bindung",
      // Selbsterhaltung faellt mit "Haltung".
      form:Math.round(SK(ZUSAMMEN,z)*100),
      opp:Math.round((1-SK(BINDUNG,b))*100),
      selb:Math.round((1-SK(HALTUNG,h))*100),
      ziel:PERS[pk].ziel
    };
  }
  // Beschreibende Neigungen — wie „Composed · Map-aware" bei Eslabong, nur abgeleitet.
  function neigungen(b){
    const o=[];
    o.push(b.form>=70?"Linientreu":b.form<=30?"Eigenmächtig":"Beweglich");
    o.push(b.opp>=70?"Wechselhaft":b.opp<=25?"Tunnelblick":"Aufmerksam");
    o.push(b.selb>=70?"Vorsichtig":b.selb<=20?"Todesmutig":"Besonnen");
    return o.join(" · ");
  }
  // ===================================================================================
  // SLOTS STATT REIHEN.
  //
  // Front/Mitte/Backrow waren meine Erfindung. Das Spiel hat laengst echte Slot-Rollen
  // (lib/lineups/matchday-slot-roles.ts), und die sagen mehr: sie legen fest, WELCHE
  // Attribute in diesem Slot zaehlen. Ein Vanguard wird nach Power und Health bewertet,
  // ein Shotcaller nach Charisma und Intelligence. Damit beeinflusst der Slot die
  // Grundwerte des Spielers, statt nur zu sagen, wo er steht.
  //
  // Die Profile werden nicht nachgebaut und auch nicht mehr abgeschrieben, sondern
  // ERZEUGT: scripts/generiere-arena-daten.ts liest die echten Quellen des Spiels und
  // schreibt den Block unten. Abschreiben ging bei zwei Disziplinen noch; bei zwanzig
  // sind es ueber 1400 Zahlen, die lautlos auseinanderlaufen koennen.
